package com.fitnutri.backend.activity.catalogue;
import com.fitnutri.backend.activity.ActivityReferenceImportService;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.support.TestDatabase;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.io.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("integration-test") @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ExerciseCatalogueSearchIT {
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @Autowired ExerciseOptionService options;@Autowired MovementCatalogueService movements;@Autowired ActivityReferenceImportService official;@Autowired ExerciseOptionImporter importer;@Autowired JdbcTemplate jdbc;
 @BeforeAll void prepare(){assertEquals("CATALOGUE_UNAVAILABLE",assertThrows(BusinessException.class,()->options.search(null,null,0,20)).code());assertThrows(BusinessException.class,()->movements.search(null,null,null,0,20));Path directory=Path.of(System.getenv().getOrDefault("TEST_REFERENCE_SOURCE_DIR",Path.of("..",".local","reference-sources").toString())).toAbsolutePath().normalize();Map<String,Resource> raw=new HashMap<>();for(String name:List.of("2024-adult-compendium.pdf","2024-adult-compendium-age-source.html"))raw.put(name,new FileSystemResource(directory.resolve(name)));official.importActivityManifest(new ClassPathResource("data/manifests/compendium-2024-r2.json"),new ClassPathResource("data/compendium-2024-activities-r2.json"),raw);importer.importImmutableCatalogueVersion(new ClassPathResource("data/ux/exercise-options-v1.json"),new ClassPathResource("data/ux/movement-catalogue-v1.json"),false);}
 @Test void categoryAndTypeRemainDistinctAndUnknownMappingIsNotMissingProduct(){assertEquals(38,options.search(null,null,0,100).totalMatches());for(String category:List.of("CARDIO","STRENGTH","SPORTS","OUTDOOR_OTHER"))assertTrue(options.search(category,null,0,100).results().stream().allMatch(r->r.category().equals(category)));var rowers=options.search("CARDIO","划船",0,100);assertTrue(rowers.results().stream().anyMatch(r->r.optionKey().equals("rowing-machine")&&r.mappingKind().equals("UNAVAILABLE")&&r.referenceId()==null&&!r.mappingReason().isBlank()));assertTrue(rowers.results().stream().anyMatch(r->r.optionKey().equals("rowing-under100w")&&r.mappingKind().equals("SPECIFIC_REFERENCE")&&r.referenceId()!=null));var strength=movements.search("BACK",null,"划船",0,100);assertFalse(strength.results().isEmpty());String expected=jdbc.queryForObject("SELECT id::text FROM exercise_option WHERE option_key='strength-general'",String.class);assertTrue(strength.results().stream().allMatch(r->r.defaultPeriodOptionId().equals(expected)));}
 @Test void bilingualAliasesBodyEquipmentAndUnknownQueriesAreSearchableWithoutGuesses(){assertTrue(options.search(null,"ＢＩＫＥ",0,100).results().size()>=3);var chest=movements.search("CHEST","MACHINE","胸推",0,20);assertEquals(1,chest.results().size());assertEquals("Seated chest press",chest.results().getFirst().displayName());assertEquals("MACHINE_DISPLAY",chest.results().getFirst().loadBasis());assertTrue(options.search("CARDIO","卧推",0,20).results().isEmpty());assertTrue(movements.search(null,null,"不存在的动作",0,20).results().isEmpty());String json=new tools.jackson.databind.ObjectMapper().writeValueAsString(chest);assertFalse(json.contains("\"metValue\""));assertFalse(json.contains("\"durationMinutes\""));assertFalse(json.contains("\"estimatedKj\""));}
 @Test void paginationIsStableAndNeverTruncatesDirectoryAtFirstPage(){var a=movements.search(null,null,null,0,10);var b=movements.search(null,null,null,1,10);assertEquals(36,a.totalMatches());assertEquals(10,a.results().size());assertTrue(a.hasMore());var ids=new HashSet<>(a.results().stream().map(MovementCatalogueService.Response::id).toList());assertTrue(b.results().stream().noneMatch(r->ids.contains(r.id())));assertEquals(a,movements.search(null,null,null,0,10));assertTrue(movements.search(null,null,null,Integer.MAX_VALUE,100).results().isEmpty());}
 @Test void disabledRowsAndInactiveDefaultsAreNotReturnedAsSelectable(){jdbc.update("UPDATE exercise_option SET active=false WHERE option_key='stationary-bike'");jdbc.update("UPDATE movement_catalogue SET active=false WHERE movement_key='plank'");try{assertTrue(options.search(null,"固定单车",0,20).results().isEmpty());assertTrue(movements.search(null,null,"平板支撑",0,20).results().isEmpty());}finally{jdbc.update("UPDATE exercise_option SET active=true WHERE option_key='stationary-bike'");jdbc.update("UPDATE movement_catalogue SET active=true WHERE movement_key='plank'");}}
 @Test void inactiveSourceAndInactiveStrengthDefaultCannotMasqueradeAsSelectable(){long ref=jdbc.queryForObject("SELECT reference_id FROM exercise_option WHERE option_key='recumbent-bike'",Long.class);jdbc.update("UPDATE exercise_type SET is_active=false WHERE id=?",ref);try{assertTrue(options.search(null,"recumbent",0,20).results().isEmpty());assertTrue(options.search(null,"垂直登山机",0,20).results().stream().allMatch(r->r.mappingKind().equals("UNAVAILABLE")));}finally{jdbc.update("UPDATE exercise_type SET is_active=true WHERE id=?",ref);}jdbc.update("UPDATE exercise_option SET active=false WHERE option_key='strength-general'");try{assertEquals("CATALOGUE_UNAVAILABLE",assertThrows(BusinessException.class,()->movements.search(null,null,null,0,20)).code());}finally{jdbc.update("UPDATE exercise_option SET active=true WHERE option_key='strength-general'");}}
}
